using System.Collections.Generic;
using Astrea.GameStates;
using Astrea.RunModifiers;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

public class CorruptedAnimalCorruptionStats : CorruptionStats
{
	[Header("Corrupted Animal Components")]
	[SerializeField]
	private CorruptedAnimalCorruptionGauge corruptedAnimalCorruptionGauge;

	[SerializeField]
	private CorruptedAnimalEffects corruptedAnimalEffects;

	[SerializeField]
	private CorruptedAnimalOverCorruption corruptedAnimalOverCorruption;

	[Header("Corrupted Animal Effects")]
	[SerializeField]
	private CorruptedAnimalEffectsList corruptedAnimalEffectsList;

	[Header("Map Handler")]
	[SerializeField]
	private MapHandler mapHandler;

	[Header("Difficulty Level")]
	[SerializeField]
	private DifficultyLevels difficultyLevels;

	[Header("Debug")]
	[SerializeField]
	private EnemyDebug enemyDebug;

	[ShowNonSerializedField]
	protected float currentOverCorruption;

	protected float maxOverCorruption;

	private CorruptedAnimalData corruptedAnimalData;

	private bool infinityCorruption;

	private const int INFINITY_CORRUPTION_VALUE = 999;

	private bool enemyDefeated;

	private bool disableOverCorruptionForTutorial;

	public CorruptedAnimalOverCorruption CorruptedAnimalOverCorruption => corruptedAnimalOverCorruption;

	public CorruptedAnimalData CorruptedAnimalData => corruptedAnimalData;

	public bool InfinityCorruption => infinityCorruption;

	public bool OverCorrupted => corruptedAnimalCorruptionGauge.OverCorrupted;

	public void SetInfinityCorruption(bool value)
	{
		infinityCorruption = value;
	}

	public void SetDisableOverCorruptionForTutorial(bool value)
	{
		disableOverCorruptionForTutorial = value;
	}

	private void Update()
	{
		if (mapHandler.GameController.IsReleaseBuildWithDebug && ((Input.GetKey(KeyCode.Q) && Input.GetKey(KeyCode.R)) || (ReferenceSingleton<InputManager>.Instance.GetLeftShoulderButtonHeld() && ReferenceSingleton<InputManager>.Instance.GetInspectButtonDown())))
		{
			currentCorruption = 1f;
			maxCorruption = 1f;
			maxOverCorruption = 1f;
			corruptedAnimalCorruptionGauge.UpdateCorruptionGauge(currentCorruption, currentOverCorruption);
		}
	}

	public void ModifyMaxCorruption(float newCurrentCorruption, float newMaxCorruption, float extraFillDuration, bool changingToInfinityCorruption = false)
	{
		corruptedAnimalCorruptionGauge.ModifyMaxCorruptionAnimatedFill(newCurrentCorruption, newMaxCorruption, extraFillDuration, changingToInfinityCorruption);
		maxCorruption = newMaxCorruption;
		currentCorruption = newCurrentCorruption;
		enemyDefeated = false;
	}

	public void Initialize(CorruptedAnimalData corruptedAnimalData, bool startBattleInitialize)
	{
		this.corruptedAnimalData = corruptedAnimalData;
		if (enemyDebug.allEnemiesOneHP)
		{
			currentCorruption = 1f;
			maxCorruption = 1f;
			maxOverCorruption = 1f;
		}
		else
		{
			int currentDifficultyLevelModifyEnemiesHighestIndex = difficultyLevels.GetCurrentDifficultyLevelModifyEnemiesHighestIndex();
			RangedInt startingCorruption = corruptedAnimalData.GetStartingCorruption(currentDifficultyLevelModifyEnemiesHighestIndex, mapHandler.CurrentAreaIndex);
			float num = 0f;
			if (ReferenceSingleton<TurnManager>.Instance.AmbushBattle)
			{
				num = startingCorruption.minValue;
			}
			else if (startingCorruption.maxValue != 0)
			{
				_ = mapHandler.CurrentAreaLevelIndex;
				float num2 = mapHandler.BattleIndexes.Count - 1;
				float num3 = 0f;
				for (int i = 0; i < mapHandler.BattleIndexes.Count; i++)
				{
					if (mapHandler.BattleIndexes[i] == mapHandler.CurrentAreaLevelIndex)
					{
						num3 = i;
					}
				}
				float num4 = startingCorruption.maxValue - startingCorruption.minValue;
				num = ((num3 - num2) / num2 + 1f) * num4 + (float)startingCorruption.minValue;
			}
			else
			{
				num = startingCorruption.minValue;
			}
			if (!corruptedAnimalData.IgnoreAnomalyLevelStartingCorruptionModifier && num != 999f)
			{
				float currentDifficultyLevelIncreaseMaxCorruptionPercentage = difficultyLevels.GetCurrentDifficultyLevelIncreaseMaxCorruptionPercentage();
				num += (float)Mathf.CeilToInt(num * currentDifficultyLevelIncreaseMaxCorruptionPercentage);
			}
			if (ReferenceSingleton<RunModifiersManager>.Instance.MonstrousVitalityRunModifierAmount > 0f && num != 999f)
			{
				num += (float)Mathf.CeilToInt(num * ReferenceSingleton<RunModifiersManager>.Instance.MonstrousVitalityRunModifierAmount);
			}
			GrimExchangeRunModifier grimExchangeRunModifier = ReferenceSingleton<RunModifiersManager>.Instance.GrimExchangeRunModifier;
			if (grimExchangeRunModifier != null)
			{
				if (num != 999f)
				{
					grimExchangeRunModifier.ReinforcedAmounts.Add(new GrimExchangeRunModifier.ReinforcedAmount(base.gameObject, Mathf.CeilToInt(num * grimExchangeRunModifier.ApplyReinforcedPercentage)));
					num += (float)Mathf.CeilToInt(num * grimExchangeRunModifier.LoseCorruptionPercentage);
				}
				else if (corruptedAnimalData.CorruptedAnimalName == "Voidsmith")
				{
					grimExchangeRunModifier.VoidsmithBattle(base.gameObject);
				}
			}
			currentCorruption = Mathf.Ceil(num);
			maxCorruption = Mathf.Ceil(num);
			maxOverCorruption = corruptedAnimalData.GetMaxOverCorruption(currentDifficultyLevelModifyEnemiesHighestIndex);
			if (!startBattleInitialize)
			{
				maxOverCorruption += ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.GetCrypticMementoOmenActionAmount();
			}
		}
		currentOverCorruption = 0f;
		corruptedAnimalCorruptionGauge.Initialize(currentCorruption, maxOverCorruption, startBattleInitialize);
		infinityCorruption = currentCorruption == 999f;
		enemyDefeated = false;
		spawnFeedbackCoroutine = null;
	}

	public void ModifyMaxOverCorruptionAnimatedFill(float newCurrentOverCorruption, float newMaxOverCorruption, float extraFillDuration)
	{
		corruptedAnimalCorruptionGauge.ModifyMaxOverCorruptionAnimatedFill(newCurrentOverCorruption, newMaxOverCorruption, extraFillDuration);
		maxOverCorruption = newMaxOverCorruption;
		currentOverCorruption = newCurrentOverCorruption;
		enemyDefeated = false;
	}

	public void ModifyMaxOverCorruption(int amount)
	{
		maxOverCorruption += amount;
		maxOverCorruption = Mathf.Clamp(maxOverCorruption, 1f, 99f);
		corruptedAnimalCorruptionGauge.ModifyMaxOverCorruption(maxOverCorruption);
		corruptedAnimalCorruptionGauge.UpdateCorruptionGauge(currentCorruption, Mathf.Min(currentOverCorruption, maxOverCorruption));
	}

	public void ModifyMaxOverCorruptionExactlyNewAmountAndZero(int amount)
	{
		maxOverCorruption = amount;
		currentOverCorruption = 0f;
		corruptedAnimalCorruptionGauge.ModifyMaxOverCorruption(maxOverCorruption);
		corruptedAnimalCorruptionGauge.UpdateCorruptionGauge(currentCorruption, currentOverCorruption);
	}

	public void ModifyOverCorruption(int amount)
	{
		currentOverCorruption += amount;
		currentOverCorruption = Mathf.Min(currentOverCorruption, maxOverCorruption);
		corruptedAnimalCorruptionGauge.UpdateCorruptionGauge(currentCorruption, currentOverCorruption);
	}

	public int Purify(int amount, GameObject source, bool playSFX)
	{
		return Purify(amount, source, CorruptionPurifyModifierEnum.NONE, playSFX);
	}

	public override int Purify(int amount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		CorruptedAnimalEffects corruptedAnimalEffects = unitEffects as CorruptedAnimalEffects;
		corruptedAnimalEffects.OnPurifyEffectsBeforeCurrentCorruptionUpdate(currentCorruption, source);
		int num = unitEffects.IsEffectActiveGetAmount(corruptedAnimalEffectsList.CorruptedDodgeEffect, activateFeedback: false);
		if (num > 0 && corruptedAnimalEffectsList.CorruptedDodgeEffect.CheckDodgePurify(num, unitEffects, source, corruptionPurifyModifierEnum))
		{
			amount = -1;
		}
		bool num2 = amount != -1;
		amount = base.Purify(amount, source, corruptionPurifyModifierEnum, playSFX);
		if (num2)
		{
			ReferenceSingleton<PurifyOmensHandler>.Instance.OnEnemyPurifiedSyzygyStarDealCorruption(base.gameObject);
		}
		if (amount > 0 || amount == EffectsValues.INFINITY_PURIFY)
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterAchievement.OnEnemyPurified(amount, this, source);
			if (unitEffects.IsEffectActive(corruptedAnimalEffectsList.HatchingChrysalisEffect, activateFeedback: false))
			{
				corruptedAnimalEffectsList.HatchingChrysalisEffect.IncreaseSerenity(base.gameObject);
			}
			if (unitEffects.IsEffectActive(corruptedAnimalEffectsList.AphoticInstinctEffect, activateFeedback: false))
			{
				corruptedAnimalEffectsList.AphoticInstinctEffect.DecreaseDoom(unitEffects, (amount == EffectsValues.INFINITY_PURIFY) ? 999 : amount);
			}
			if (unitEffects.IsEffectActive(corruptedAnimalEffectsList.VortexBubbleEffect, activateFeedback: false) && corruptedAnimalEffectsList.VortexBubbleEffect.CheckVortexBubbleEffect((amount == EffectsValues.INFINITY_PURIFY) ? 999 : amount))
			{
				unitEffects.IsEffectActiveWithActivation(corruptedAnimalEffectsList.VortexBubbleEffect, activateFeedback: false, updateAmount: false);
			}
			InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 2, delegate
			{
				if (!IsDefeated())
				{
					int num3 = unitEffects.IsEffectActiveGetAmount(corruptedAnimalEffectsList.WaveEffect, activateFeedback: false);
					if (num3 > 0)
					{
						corruptedAnimalEffectsList.WaveEffect.CheckWaveTrigger(num3, base.gameObject);
					}
				}
			});
			if (corruptedAnimalEffects.IsEffectActive(corruptedAnimalEffectsList.DeepnessPresenceEffect, activateFeedback: false) && !unitEffects.IsEffectActiveWithActivation(corruptedAnimalEffectsList.DontOvercorruptEffect))
			{
				currentOverCorruption += ((amount == EffectsValues.INFINITY_PURIFY) ? 999 : amount);
				currentOverCorruption = Mathf.Min(currentOverCorruption, maxOverCorruption);
			}
			if (unitEffects.IsEffectActive(corruptedAnimalEffectsList.UncontrollableMeissaEffect, activateFeedback: false))
			{
				corruptedAnimalEffectsList.UncontrollableMeissaEffect.MeissaPurified(source, this);
			}
		}
		return amount;
	}

	protected override int GetPurifyAmountWithDefensiveModifiers(int amount)
	{
		int num = unitEffects.IsEffectActiveGetAmount(corruptedAnimalEffectsList.SkinCorruptionSourceLinkEffect);
		amount = Mathf.Max(amount - num, 0);
		return base.GetPurifyAmountWithDefensiveModifiers(amount);
	}

	protected override int GetAfterMinimizePurifyModifier(int amount, GameObject source)
	{
		amount = ReferenceSingleton<PurifyOmensHandler>.Instance.OnEnemiesReceivePurifyModifiers(amount);
		int num = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<UnitEffects>().IsFissionExpertiseGetAmount();
		if (num > 0)
		{
			PlayerEffects component = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>();
			if (component.IsPlayerAstriumGetAmount(activateFeedback: false) > 0)
			{
				component.IsPlayerAstriumDecreaseEffect(1);
				amount += num;
				unitEffects.IsFissionExpertiseActive();
			}
		}
		return base.GetAfterMinimizePurifyModifier(amount, source);
	}

	public void InstantlyDefeatEnemy(bool minionDefeatedByBossDefeat = false)
	{
		currentCorruption = 0f;
		UpdateCorruption(CorruptionPurifyModifierEnum.NONE);
		if (!minionDefeatedByBossDefeat)
		{
			PurifiedMoreThanCorrupted();
		}
		else
		{
			EnemyDefeated(minionDefeatedByBossDefeat: true);
		}
	}

	public override int Corrupt(int amount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		amount = ReferenceSingleton<MiscOmensHandler>.Instance.OnEnemyCorruptedDecimatorSkullModifier(amount);
		return base.Corrupt(amount, source, corruptionPurifyModifierEnum, playSFX);
	}

	protected override void OnCorruptionBlocked(int corruptionBlockedAmount, GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayerOrCompanions(source))
		{
			ReferenceSingleton<HeveliusOmensHandler>.Instance.OnEnemyCorruptionBlocked(base.gameObject, corruptionBlockedAmount);
		}
	}

	protected override void ChangeCurrentCorruption(int amount, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum)
	{
		if (amount < 0 && infinityCorruption)
		{
			return;
		}
		if (amount > 0 && enemyDefeated && currentCorruption > 0f)
		{
			currentCorruption = 0f;
			return;
		}
		base.ChangeCurrentCorruption(amount, corruptionPurifyModifierEnum);
		if (amount > 0 && !disableOverCorruptionForTutorial && !ReferenceSingleton<SothisOmensHandler>.Instance.IsEtherealPlumeOmenActiveAndAfflictionCorruption(corruptionPurifyModifierEnum) && !unitEffects.IsEffectActiveWithActivation(corruptedAnimalEffectsList.DontOvercorruptEffect))
		{
			Debug.Log("Change Current Corruption - Over Corruption Before Change " + currentOverCorruption);
			currentOverCorruption += amount;
			currentOverCorruption = Mathf.Min(currentOverCorruption, maxOverCorruption);
			Debug.Log("Change Current Corruption - Over Corruption After Change " + currentOverCorruption);
		}
	}

	protected override void UpdateCorruption(CorruptionPurifyModifierEnum corruptionPurifyModifierEnum)
	{
		if (IsDefeated())
		{
			corruptedAnimalCorruptionGauge.UpdateCorruptionGauge(0f, currentOverCorruption);
			return;
		}
		base.UpdateCorruption(corruptionPurifyModifierEnum);
		Debug.Log("UpdateCorruption - currentOverCorruption: " + currentOverCorruption);
		corruptedAnimalCorruptionGauge.UpdateCorruptionGauge(currentCorruption, currentOverCorruption);
	}

	protected override void CorruptedMoreThanPurified()
	{
		spriteControl.OnReceiveCorruption();
	}

	protected override void PurifiedMoreThanCorrupted()
	{
		if (currentCorruption <= 0f)
		{
			EnemyDefeated(minionDefeatedByBossDefeat: false);
		}
		else
		{
			spriteControl.OnReceivePurify();
		}
	}

	private void EnemyDefeated(bool minionDefeatedByBossDefeat)
	{
		if (enemyDefeated)
		{
			spriteControl.OnReceivePurify();
			return;
		}
		enemyDefeated = true;
		CorruptedAnimalSpriteControl corruptedAnimalSpriteControl = spriteControl as CorruptedAnimalSpriteControl;
		if (corruptedAnimalEffects.IsEffectActive(corruptedAnimalEffectsList.OmniSoulEffect, activateFeedback: false))
		{
			List<EffectInstance> activeEffectsListBeforeRemoval = corruptedAnimalEffects.activeEffectsList.Duplicate();
			corruptedAnimalSpriteControl.OnReceiveFatalDamage(minionDefeatedByBossDefeat);
			corruptedAnimalEffectsList.OmniSoulEffect.OneAstreaDefeatedTurnIntoBall(base.gameObject, activeEffectsListBeforeRemoval);
			return;
		}
		corruptedAnimalSpriteControl.OnReceiveFatalDamage(minionDefeatedByBossDefeat);
		ActionsQueueState actionsQueueState = ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState;
		if (corruptedAnimalData.CorruptionSource)
		{
			actionsQueueState.CorruptionSourcePurged = true;
		}
		actionsQueueState.CurrentCorruptedAnimals.activeCorruptedAnimals.Remove(base.gameObject);
		ReferenceSingleton<AssetsReference>.Instance.IndigoRiteAction.IndigoRiteTriggerCheck();
	}

	public void OnEndCorruptPlayerState()
	{
	}

	public void OnActionsOnQueueEnded()
	{
		if (corruptedAnimalCorruptionGauge.OverCorrupted)
		{
			SetOverCorruptionToZero();
		}
	}

	public void SetOverCorruptionToZero()
	{
		Debug.Log("SetOverCorruptionToZero - currentOverCorruption: " + currentOverCorruption);
		currentOverCorruption = 0f;
		corruptedAnimalCorruptionGauge.UpdateCorruptionGauge(currentCorruption, currentOverCorruption);
	}

	public void OnToggleEnemyOneHP()
	{
		Initialize(corruptedAnimalData, startBattleInitialize: false);
	}

	public override bool IsDefeated()
	{
		if (!(currentCorruption <= 0f))
		{
			return enemyDefeated;
		}
		return true;
	}

	public float GetOverCorruptionPercentage()
	{
		return currentOverCorruption / maxOverCorruption;
	}
}
